<?php
namespace App\Console\Commands;
use App\Models\{AttendancePolicy,Campus,StudentAttendance};use App\Services\SmsService;use Illuminate\Console\Command;
class SendAutomaticAbsentNotifications extends Command{
 protected $signature='attendance:notify-absent {date?}';protected $description='Send idempotent guardian SMS notifications for absent students';
 public function handle():int{$date=$this->argument('date')?:today()->toDateString();$sent=0;$skipped=0;foreach(Campus::where('is_active',true)->cursor()as$campus){config(['app.active_campus_id'=>$campus->id]);$policy=AttendancePolicy::where('is_active',true)->first();if(!$policy?->auto_absent_sms)continue;StudentAttendance::with('student.guardian')->whereDate('attendance_date',$date)->where('status','absent')->where('is_excused',false)->chunkById(200,function($rows)use(&$sent,&$skipped,$date,$campus){foreach($rows as$row){$student=$row->student;$guardian=$student?->guardian;$preferences=$guardian?->notification_preferences??[];if(array_key_exists('attendance',$preferences)&&!$preferences['attendance']){$skipped++;continue;}$phone=$guardian?->father_phone?:($guardian?->mother_phone?:$student?->phone);if(!$phone){$skipped++;continue;}$message="সম্মানিত অভিভাবক, আপনার সন্তান {$student->first_name} ".\Carbon\Carbon::parse($date)->format('d-m-Y')." তারিখে বিদ্যালয়ে অনুপস্থিত। অনুগ্রহ করে বিদ্যালয়ে যোগাযোগ করুন।";SmsService::send($phone,$message,['campus_id'=>$campus->id,'recipient_name'=>$guardian?->father_name?:$student->first_name,'recipient_type'=>'guardian','recipient_id'=>$guardian?->id,'student_id'=>$student->id,'category'=>'attendance','reference_key'=>'auto-absent:'.$row->id])?$sent++:$skipped++;}});}config(['app.active_campus_id'=>null]);$this->info("Absent notifications: {$sent} sent, {$skipped} skipped.");return self::SUCCESS;}
}
